import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';
import axios from 'axios';
import { motion, AnimatePresence } from 'framer-motion'; // For Requirement 5 animations
import './AuctionDashboard.css';

const token = localStorage.getItem('token');
const socket = io('BACKEND_URL', { auth: { token } });

const AuctionDashboard = () => {
    const [player, setPlayer] = useState(null);
    const [highestBid, setHighestBid] = useState(0);
    const [highestBidder, setHighestBidder] = useState('No bids yet');
    const [timer, setTimer] = useState(30);
    const [isActive, setIsActive] = useState(false);
    const [history, setHistory] = useState([]);
    const [eventName, setEventName] = useState('');
    const [viewers, setViewers] = useState(0);
    const [ownerTeam, setOwnerTeam] = useState(() => {
        const raw = localStorage.getItem('team');
        return raw ? JSON.parse(raw) : null;
    });
    const [eventConfig, setEventConfig] = useState(null);
    const [bidToast, setBidToast] = useState(null);
    const [resultOverlay, setResultOverlay] = useState(null);
    const [playerStatus, setPlayerStatus] = useState(null);

    // NEW STATES FOR REQUIREMENT 5
    const [countdown321, setCountdown321] = useState(null); 
    const [timerPhase, setTimerPhase] = useState('normal'); // 'normal', 'warning', 'critical'

    const user = JSON.parse(localStorage.getItem('user'));

    useEffect(() => {
        socket.on("auction_started", (data) => {
            setPlayer(data.currentPlayer);
            setHighestBid(data.highestBid);
            setHighestBidder(data.highestBidder);
            setTimer(data.timer);
            setHistory(data.bidHistory);
            setIsActive(true);
            setCountdown321(null); // Clear any old countdowns
            setEventName(data.currentPlayer?.event?.name || '');
        });

        // REQUIREMENT 5: 3-2-1 TIMER SYNC
        socket.on("timer_tick", (count) => {
            setCountdown321(count);
            if (count === 3) setTimerPhase('normal');
            if (count === 2) setTimerPhase('warning');
            if (count === 1) setTimerPhase('critical');
            if (count === 0) {
                setCountdown321("SOLD!");
                setTimeout(() => setCountdown321(null), 2000);
            }
        });

        socket.on("timer_update", (timeLeft) => {
            setTimer(timeLeft);
            // Requirement 3: Reset behavior handled by backend, frontend updates UI phase
            if (timeLeft <= 10) setTimerPhase('warning');
            else setTimerPhase('normal');
        });

        socket.on("bid_placed", (data) => {
            setBidToast({ teamName: data.teamName, amount: data.amount });
            setTimeout(() => setBidToast(null), 2200);
        });

        /* ... rest of your existing socket.on listeners (auction_result, viewer_count, etc.) ... */

        return () => {
            socket.off("auction_started");
            socket.off("timer_tick");
            socket.off("timer_update");
            socket.off("bid_placed");
            // ... off for other listeners
        };
    }, []);

    const handlePlaceBid = () => {
        if (!ownerTeam) return alert("Only Team Owners can bid!");
        const nextBid = highestBid + 500000;

        socket.emit("place_bid", {
            teamId: ownerTeam._id,
            teamName: ownerTeam.teamName,
            bidAmount: nextBid
        });
    };

    const nextBidAmount = highestBid + 500000;
    const isBidDisabled = !user || user.role !== 'Owner' || (ownerTeam?.remainingBudget < nextBidAmount);

    return (
        <div className={`auction-root phase-${timerPhase}`}>
            {/* REQUIREMENT 4: Non-clickable Logo (Added to Navbar) */}
            <header className="auction-nav">
                <div className="auction-pro-logo">AUCTION-PRO</div>
                <div className="nav-meta">
                    {viewers} <i className="fas fa-eye"></i>
                </div>
            </header>

            {/* REQUIREMENT 5: 3-2-1 Animation Overlay */}
            <AnimatePresence>
                {countdown321 !== null && (
                    <motion.div 
                        initial={{ scale: 0, opacity: 0 }}
                        animate={{ scale: 1.2, opacity: 1 }}
                        exit={{ scale: 2, opacity: 0 }}
                        className={`countdown-overlay phase-${timerPhase}`}
                    >
                        <h1>{countdown321}</h1>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* REQUIREMENT 5: Bid Notification Banner */}
            <AnimatePresence>
                {bidToast && (
                    <motion.div 
                        initial={{ x: 100, opacity: 0 }}
                        animate={{ x: 0, opacity: 1 }}
                        exit={{ x: 100, opacity: 0 }}
                        className="bid-banner-popup"
                    >
                        <strong>{bidToast.teamName}</strong> bid ₹{bidToast.amount.toLocaleString()}!
                    </motion.div>
                )}
            </AnimatePresence>

            {!isActive ? (
                <div className="auction-container glass-bg">
                    <div className="waiting-card">
                        <div className="pulse-loader"></div>
                        <h2>Waiting for the next player...</h2>
                    </div>
                </div>
            ) : (
                <div className="auction-main-layout">
                    {/* PLAYER CARD SECTION */}
                    <div className="player-card-container">
                        <div className={`player-card-main card-shadow ${timer <= 10 ? 'timer-warning' : ''}`}>
                            <div className="timer-badge">{timer}s</div>
                            <div className="player-image-wrapper">
                                <img src={player?.photo || 'default-avatar.png'} alt={player?.name} />
                            </div>
                            <div className="player-info-content">
                                <h2>{player?.name}</h2>
                                <p className="pill-category">{player?.role}</p>
                                <div className="stats-grid">
                                    <div className="stat-item"><span>Runs</span><strong>{player?.stats?.runs}</strong></div>
                                    <div className="stat-item"><span>Wkts</span><strong>{player?.stats?.wickets}</strong></div>
                                </div>
                            </div>

                            <div className="bid-status-box bid-animation">
                                <p>Current Bid</p>
                                <h3 className="bid-highlight">₹{highestBid.toLocaleString()}</h3>
                                <p className="bidder-name">by {highestBidder}</p>
                            </div>

                            {user?.role === 'Owner' && (
                                <button 
                                    className="bid-action-btn" 
                                    onClick={handlePlaceBid} 
                                    disabled={isBidDisabled}
                                >
                                    {isBidDisabled ? 'LOCKED' : `BID ₹${nextBidAmount.toLocaleString()}`}
                                </button>
                            )}
                        </div>
                    </div>

                    {/* HISTORY LOG */}
                    <div className="bidding-log-sidebar card-shadow">
                        <h3>Live Bid History</h3>
                        <div className="log-container">
                            {history.map((bid, i) => (
                                <div key={i} className="log-entry">
                                    <span>{bid.bidder}</span>
                                    <strong>₹{bid.amount.toLocaleString()}</strong>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default AuctionDashboard;
